// Site data contract, schema_version 1. Generated by playbook/export.py.
// Source of truth: DESIGN.md, "Site data contract". Breaking changes require a schema_version bump.
// Optional hub metadata is additive and remains compatible with older schema 1 exports.

export type Side = "T" | "CT";
export type Lane = "T_SPAWN" | "A" | "MID" | "B" | "CT_SPAWN" | "OTHER";
export type GrenadeType = "smoke" | "flashbang" | "molotov" | "he";
export type Technique = "jump" | "run" | "crouch" | "walk" | "stand";
export type BuyType = "pistol" | "eco" | "force" | "full";
export type ExecuteTiming = "fast" | "default_then_execute" | "late" | "no_clear_execute";
export type Role = "awper" | "a_anchor" | "b_anchor" | "mid_ct" | "lurker" | "entry" | "support";

/** A ranked value with its sample: setups, plant sites, execute timing, ... */
export interface Ranked<V = string> {
  value: V;
  rounds: number;
  share: number | null;
  won: number;
  win_rate: number | null;
}

export interface SiteIndex {
  schema_version: 1;
  generated_at: string;
  min_matches_reliable: number;
  data_source: string;
  maps: {
    map: string;
    display_name: string;
    n_matches: number;
    teams: string[]; // team slugs
    n_players: number;
    n_lineups: number;
    /** true when <map>/heatmaps/ exists */
    heatmaps?: boolean;
    win_rate_T?: number | null;
    win_rate_CT?: number | null;
    top_recipe?: { id: string; name: { zh: string; en: string } } | null;
  }[];
}

export interface MapMeta {
  map: string;
  display_name: string;
  /** radar_x = (x - pos_x) / scale ; radar_y = (pos_y - y) / scale, on a 1024x1024 image */
  radar: { pos_x: number; pos_y: number; scale: number; lower_level_max_z?: number };
  radar_image: string;
  regions: Record<string, Lane>; // region -> lane
  callouts: Record<string, string>; // callout -> region
}

export interface TeamSummary {
  team: string;
  slug: string;
  n_matches: number;
  low_sample: boolean;
  win_rate_T: number | null;
  win_rate_CT: number | null;
}

interface SideCommon {
  rounds: number;
  won: number;
  win_rate: number | null;
  gun_rounds: number;
  opening_win_rate: number | null;
  avg_first_kill_s: number | null;
  avg_util_per_round: number | null;
  avg_early_util: number | null;
  /** lane shape of living players, e.g. "A2 M2 B1" (S = T spawn, C = CT spawn), gun rounds only */
  setups_15s: Ranked[];
  setups_30s: Ranked[];
}

export interface TSide extends SideCommon {
  plant_sites: Ranked<"A" | "B" | "none">[];
  avg_plant_t_s: number | null;
  execute_timing: Ranked<ExecuteTiming>[];
  execute_lane: Ranked<Lane>[];
  avg_execute_start_s: number | null;
}

export interface CTSide extends SideCommon {
  plants_against: number;
  retakes_won: number;
  retake_win_rate: number | null;
  plants_against_by_site: Ranked<"A" | "B">[];
  stack_rate_15s: number | null;
}

export interface TeamProfile {
  team: string;
  slug: string;
  map: string;
  n_matches: number;
  low_sample: boolean;
  matches: {
    demo_id: string;
    hltv_match_id: number | null;
    opponent: string | null;
    score_for: number;
    score_against: number;
    winprob_available?: boolean;
    event?: string | null;
    event_name?: string | null;
    date?: string | null;
  }[];
  sides: { T: TSide; CT: CTSide };
  economy: { side: Side; buy_type: BuyType; rounds: number; won: number; win_rate: number | null }[];
  /** M2 tactic identification, gun rounds only (playbook/tactics.py) */
  tactics?: { T: TTactics; CT: CTTactics };
  /** checked facts vs the other teams on this map (playbook/insights.py) */
  insights?: Insight[];
  /** short analyst paragraph written from `insights` by an LLM, numbers checked (scripts/insight_text.py) */
  summary?: { zh: string; en: string; facts: string[] };
}

export interface Share {
  value: string;
  share: number | null;
}

export interface RoleHint {
  role: Role;
  metric: string;
  value: number | null;
  team_median?: number;
}

export interface PlayerProfile {
  steamid: string;
  name: string;
  team: string;
  n_matches: number;
  rounds: { total: number; T: number; CT: number };
  kpr: number | null;
  dpr: number | null;
  hs_pct: number | null;
  opening_kills_pr: number | null;
  opening_deaths_pr: number | null;
  opening_success: number | null;
  traded_death_rate: number | null;
  awp_share: number | null;
  util_pr: number | null;
  T: {
    avg_dist_to_team_30s: number | null;
    first_into_site_rate: number | null;
    lanes_15s: Share[];
    places_30s: Share[];
    /** share of the team's committed T gun rounds in which he was the lurker */
    lurk_share?: number | null;
    wpa?: Wpa;
  };
  CT: {
    lanes_15s: Share[];
    places_30s: Share[];
    /** share of the team's CT gun rounds in which he stood forward (T territory) at 15 s */
    forward_share?: number | null;
    wpa?: Wpa;
  };
  role_hints: RoleHint[];
}

export interface Lineup {
  id: string;
  side: Side;
  type: GrenadeType;
  throw_place: string | null;
  land_place: string | null;
  land_region: string | null;
  land_lane: Lane | null;
  n_throws: number;
  n_matches: number;
  teams: string[];
  throwers: string[];
  round_win_rate: number | null;
  median_pop_t_s: number | null;
  technique: Technique;
  jump_share: number | null;
  throw: { x: number; y: number; z: number; pitch: number; yaw: number; radar_x: number; radar_y: number };
  land: { x: number; y: number; z: number; radar_x: number; radar_y: number };
  /** paste into the CS2 console on a practice server (sv_cheats 1) */
  practice_cmd: string;
  example: { demo_id: string; round_num: number; throw_tick: number };
}

// ---------------------------------------------------------------------------- heatmaps
// <map>/heatmaps/baseline.json and <map>/heatmaps/teams/<slug>.json (playbook/heatmap.py, playbook/zones.py)
// Cleaned data: gun rounds of the team only, living time only, first 5 s and post-round excluded.

export type HeatLayer =
  | "presence" // living seconds
  | "holding" // living seconds moving < 40 units/s
  | "shots"
  | "kills" // at the attacker
  | "deaths" // at the victim
  | "smoke" // grenade LANDING points by type
  | "flash"
  | "molotov"
  | "he";
export type HeatPhase = "early" | "mid" | "post";

/**
 * Sparse grid: [cell, value, cell, value, ...].
 * cell = level * grid * grid + row * grid + col (row 0 = top of the radar image).
 * value = per round played on that side: seconds (presence, holding) or counts.
 */
export type SparseGrid = number[];

export interface HeatGrid {
  /** totals per round, by side and phase ("all" = sum of phases) */
  per_round: Partial<Record<Side, Partial<Record<HeatPhase | "all", Partial<Record<HeatLayer, number>>>>>>;
  data: Partial<Record<Side, Partial<Record<HeatPhase, Partial<Record<HeatLayer, SparseGrid>>>>>>;
}

/** Grid metadata plus all teams on the map together (per team gun round). */
export interface HeatmapBaseline extends HeatGrid {
  map: string;
  grid: number; // cells per side (64)
  cell_px: number; // radar pixels per cell (16)
  levels: 1 | 2; // 2 on maps with a lower floor (Nuke): level 1 = radars/<map>_lower.png
  layers: HeatLayer[];
  phases: HeatPhase[];
  sides: Side[];
  n_colors: number; // 5: red, blue, purple, green, orange
  early_s: number;
  spawn_skip_s: number;
  hold_speed: number;
  gun_rounds_only: boolean;
  min_reliable_rounds: number;
  value: string;
  cell_index: string;
  rounds: { T: number; CT: number };
}

/** data/heatmap_teams.json: entry point of the heatmap pages (team first, then map). */
export interface HeatmapTeamIndexEntry {
  team: string;
  slug: string;
  n_matches: number; // all maps
  /** maps with heatmap data for this team, most played first (the arrow order) */
  maps: {
    map: string; display_name: string; n_matches: number;
    rounds: { T: number; CT: number }; players: string[];
    /** Additive hub fields; optional for older exports. Rates use all rounds/maps. */
    map_win_rate?: number | null;
    round_win_rate?: number | null;
    win_rate_T?: number | null;
    win_rate_CT?: number | null;
    all_rounds?: number;
    low_sample?: boolean;
    results?: TeamProfile["matches"];
  }[];
  /** fixed colours on every map: 0 red, 1 blue, 2 purple, 3 green, 4 orange, >= 5 grey */
  roster: { steamid: string; name: string; color: number; rounds: number }[];
}

export interface AssetSlots { teams: string[]; players: string[] }

export type PlayerQuotes = Record<string, { name: string; zh: string; en: string }>;

export interface RosterEntry {
  steamid: string;
  name: string;
  /** 0 red, 1 blue, 2 purple, 3 green, 4 orange, >= 5 grey (substitutes); same on every map */
  color: number;
  rounds: { T: number; CT: number }; // gun rounds for this team on this map
  low_sample: { T: boolean; CT: boolean }; // rounds < min_reliable_rounds
}

export interface ZoneShare {
  place: string;
  region: string;
  lane: Lane;
  share: number | null;
}

export interface HoldSpot {
  place: string;
  lane: Lane;
  x: number;
  y: number;
  z: number;
  radar_x: number;
  radar_y: number;
  level: number;
  seconds_per_round: number | null;
  share_of_holding: number | null;
  rounds_held: number; // rounds with >= 2 s held there
  median_t_s: number | null;
  phases: Record<HeatPhase, number | null>; // share of that hold's seconds in each phase
}

export interface UtilitySpot {
  level: number;
  spot_id: string;
  type: GrenadeType;
  place: string | null;
  label: string | null;
  radar_x: number | null;
  radar_y: number | null;
  n: number;
  per_round: number | null;
  median_t_s: number | null; // throw time
  lineups: { lineup_id: string; n: number }[]; // ids in <map>/lineups.json
}

export interface PlayerSideSummary {
  rounds: number;
  zones: Partial<Record<HeatPhase, ZoneShare[]>>;
  main_lane: Partial<Record<HeatPhase, { lane: Lane; share: number | null }>>;
  holds: HoldSpot[];
  fights: {
    kills_pr: number | null;
    deaths_pr: number | null;
    opening_kills: number;
    opening_deaths: number;
    places: { place: string; kills: number; deaths: number }[];
  };
  utility: {
    per_round: { smoke: number | null; flash: number | null; molotov: number | null; he: number | null };
    spots: UtilitySpot[];
    unclustered?: number;
  };
}

export interface TeamHeatmap {
  team: string;
  slug: string;
  map: string;
  n_matches: number;
  rounds: { T: number; CT: number }; // team gun rounds
  roster: RosterEntry[]; // sorted by colour
  team_grid: HeatGrid; // whole team, per team round
  players: Record<string, HeatGrid>; // by steamid, per player round
  summary: Record<string, Partial<Record<Side, PlayerSideSummary>>>;
  /** which players are mainly on which lane, per side and phase */
  setup: Partial<Record<Side, Partial<Record<HeatPhase, Partial<Record<Lane, string[]>>>>>>;
}

// ----------------------------------------------------------------------------- tactics
// <map>/tactics.json and TeamProfile.tactics (playbook/tactics.py). Gun rounds only.

export type Tempo = "fast" | "mid" | "late" | "no_hit";

export interface TTactics {
  gun_rounds: number;
  tempo: Ranked<Tempo>[];
  target: Ranked<"A" | "B" | "none">[]; // site actually hit (commit or plant)
  attempt: Ranked<"A" | "B" | "none">[]; // target, or the site a failed execute went for
  avg_commit_s: number | null;
  split_rate: number | null; // of rounds with a commit
  lurk_rate: number | null;
  fake_rate: number | null;
  recipes: Ranked[]; // value = Recipe.id
  lurkers: { steamid: string; name: string; rounds: number }[];
}

export interface CTTactics {
  gun_rounds: number;
  setups_20s: Ranked[]; // lane shape at 20 s, e.g. "A2 M1 B1 C1"
  forward_rate: number | null; // rounds with >= 1 CT forward at 15 s
  forward_players: { steamid: string; name: string | null; rounds: number; share: number | null }[];
  stack_rate: number | null;
  stacks: Ranked<"A" | "B">[];
  rotation: {
    rounds: number; // rounds with a T commit
    avg_far_players: number | null; // CTs on the other site's lane 5 s before the commit
    avg_rotated: number | null; // of those, how many reached the target lane in time
    avg_delay_s: number | null;
    avg_pre_rotated: number | null; // change of CTs on the target lane between 20 s and commit-5 s
  };
}

export interface SpotRef {
  thrower?: string | null;
  order?: number | null;
  spot_id: string;
  type: "smoke" | "molotov";
  label: string; // fallback name: callout (+ "#n")
  name: { en: string | null; zh: string | null } | null; // config/spots/<map>.toml
  place: string | null;
  share: number; // share of the recipe's rounds using this spot
  lineups: { lineup_id: string; n_throws: number }[]; // throw positions, ids in lineups.json
}

export interface Recipe {
  id: string; // e.g. de_mirage-a-r01
  site: "A" | "B";
  core: SpotRef[]; // used in >= 50% of its rounds
  options: SpotRef[]; // 20-50%
  n_rounds: number;
  n_matches: number;
  teams: { team: string; rounds: number }[];
  won: number;
  win_rate: number;
  plant_rate: number;
  median_commit_s: number;
  tempo: { value: Tempo; rounds: number }[];
  avg_flashes: number;
  split_rate: number;
  examples: { demo_id: string; round_num: number; team: string }[];
  /** mean T win probability 5 s before the commit and 10 s after (playbook/winprob.py); compare recipes, not absolute effect */
  wp?: { n: number; before: number; after: number; delta: number };
  /** typical T entry routes from round start to the commit (playbook/tactics.py recipe_routes); points in radar px */
  routes?: RecipeRoute[];
}

export interface Spot {
  spot_id: string;
  side: Side;
  type: GrenadeType;
  place: string | null;
  label: string;
  name: { en: string | null; zh: string | null } | null; // from config/spots/<map>.toml when named
  region: string;
  lane: Lane;
  x: number;
  y: number;
  z: number;
  radar_x: number;
  radar_y: number;
  level: number;
  n_throws: number;
  n_matches: number;
  median_pop_t_s: number | null;
  lineups: { lineup_id: string; n_throws: number }[];
  in_recipes: boolean;
}

export interface TacticsFile {
  map: string;
  definitions: Record<string, unknown>;
  t_overview: TTactics;
  ct_overview: CTTactics;
  recipes: Recipe[];
  spots: Spot[];
}

export interface Insight {
  id: string; // e.g. t_tempo_fast, t_signature_recipe, ct_default_setup
  side: Side;
  kind: "compare" | "signature";
  value: number; // share for this team
  baseline?: number; // other teams on the map (compare facts)
  rounds: number;
  z?: number; // two-proportion z score (compare facts, |z| >= 2)
  direction?: "more" | "less";
  text: { zh: string; en: string }; // template sentence; never edit numbers by hand
  recipe_id?: string;
  steamid?: string;
  name?: string;
  shape?: string;
  won?: number;
  win_rate?: number;
}

// ----------------------------------------------------------------------------- win probability
// playbook/winprob.py: out-of-fold T-side round win probability on 1 Hz states.

/** win probability added per round on this side: duels = kills + deaths, utility = grenade pops */
export interface Wpa {
  rounds: number; per_round: number; duels: number;
  /** grenade pops, 2 s window: noisy, delayed effects are missed — do not headline it */
  utility: number;
  /** per_round × 24: extra rounds won per full match */
  rounds_per_match?: number;
  /** share of players on this map and side (≥ 50 rounds) at or below this value; null when the sample is small */
  percentile?: number | null;
  peers?: number;
}

/** <map>/winprob/<demo_id>.json, showcase teams only: T win probability per second, per round */
export interface WinprobTimeline { demo_id: string; wp_t: Record<string, number[]>; team_sides?: Record<string, Record<string, Side>> }

/** one entry route: medoid player path of a group sharing the same choke callouts */
export interface RecipeRoute { via: string[]; lane: string; n: number; share: number; points: [number, number][] }
